#!/usr/bin/env python3
"""ऋषि: materialize two law T5M pairs minted locally with zig 0.16.0."""
from pathlib import Path
import base64, subprocess

def root():
    try:
        return Path(subprocess.check_output(["git", "rev-parse", "--show-toplevel"], text=True).strip())
    except Exception:
        return Path(__file__).resolve().parents[1]

PAIRS = {
    "d10-empty-queue-law": {
        "sens": "ZzhmxHU4dhLHBkMgFgyoXYltfschQlMWHqh2iXgtyiE5Ji3DLaQuqUKpQR0VxHU4dhLHBkMgFgyoXYltfschQlMWHqh2iXgtyiE5Ji3EfsMtxnKJY4kGjC6psUGJOy6pRTyM",
        "view": "",
    },
    "d3-proper-tail-hot-law": {
        "sens": "ZzhmxFs4HxLJKkMFFiepUjgfLcZ7QlwWCal1iWxjyQ85cRYEqVWJbGPGKkJcFlSxQQ82sYlnOGbEWzgfEskqQwUWJ6lSOB8txntCXBYJqXWJbGPJDzlxFgSpVYlsY8YqQlwWVLFBe0EPObFBe0EPP7FBDzaxjC3DV0FnHqhdOHV+yQ9CdxYDqF2JbX7HIUIdFm2pUjh1LaxgQg4WDalSOGx+xyFDCy3EfsMtrS3DLb8usYwVw2BBDzaxiWQSw2BBDzaxjC6xQWQtwy2kLqk5OGQtwy2kLrGM",
        "view": "",
    },
}

r = root()
sem = r / "tests" / "semantic"
for stem, blobs in PAIRS.items():
    sens = sem / f"{stem}.sens"
    view = sem / stem
    sens.write_bytes(base64.b64decode(blobs["sens"]))
    view.write_bytes(base64.b64decode(blobs["view"]))
    print("minted", sens.name, sens.stat().st_size, "B;", view.name, view.stat().st_size, "B")
